import React, { useState } from 'react';
import './Calendrier.css';
import AjouterTrajet from './AjouterTrajet';

const Calendrier = () => {
  const [activeTab, setActiveTab] = useState('Semaine');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);

  const headerTabs = ['Aujourd\'hui', 'Personne', 'Semaine']; // Nouveaux onglets du header
  
  const joursSemaine = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];
  
  const timeSlots = ['08:00', '09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00'];
  
  const personnes = [
    { id: 1, name: 'Loïc', color: '#e3f2fd' },
    { id: 2, name: 'Paul', color: '#f3e5f5' },
    { id: 3, name: 'Jose', color: '#e8f5e9' },
    { id: 4, name: 'Jean', color: '#fff3e0' },
    { id: 5, name: 'Jase', color: '#fce4ec' }
  ];

  const planningData = {
    'Lundi': ['Loïc', 'Paul'],
    'Mardi': ['Jose', 'Jean'],
    'Mercredi': ['Loïc', 'Paul'],
    'Jeudi': ['Jose', 'Jean'],
    'Vendredi': ['Loïc', 'Paul'],
    'Samedi': ['Jase', 'Jean'],
    'Dimanche': ['Loïc', 'Paul']
  };

  const formatDate = (date) => {
    const options = { day: 'numeric', month: 'long', year: 'numeric' };
    return date.toLocaleDateString('fr-FR', options);
  };

  const handlePrevDay = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() - 1);
    setCurrentDate(newDate);
  };

  const handleNextDay = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + 1);
    setCurrentDate(newDate);
  };

  const handleToday = () => {
    setCurrentDate(new Date());
  };

  const handleSaveTrajet = (trajetData) => {
    console.log('Trajet enregistré:', trajetData);
    setShowModal(false);
  };

  return (
    <div className="page-content full-width">
      {/* Header simplifié */}
      <div className="calendrier-header">
        {/* Onglets Aujourd'hui/Personne/Semaine */}
        <div className="header-tabs-container">
          {headerTabs.map(tab => (
            <button
              key={tab}
              className={`header-tab-button ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Bouton Ajouter Trajet à droite */}
        <button 
          className="add-trajet-btn"
          onClick={() => setShowModal(true)}
        >
          <span>+</span>
          Ajouter un trajet
        </button>
      </div>

      {/* Contrôles de date (sous le header) */}
      <div className="date-controls-bar">
        <div className="date-info">
          <span className="current-date-display">
            {formatDate(currentDate)}
          </span>
        </div>
        
        <div className="date-navigation">
          <button className="nav-button" onClick={handlePrevDay} title="Jour précédent">
            ‹
          </button>
          <button className="nav-button today-button" onClick={handleToday}>
            Aujourd'hui
          </button>
          <button className="nav-button" onClick={handleNextDay} title="Jour suivant">
            ›
          </button>
        </div>

        {/* Filtre Personne */}
        <div className="person-filter">
          <select className="person-select">
            <option>Tous</option>
            <option>Loïc</option>
            <option>Paul</option>
            <option>Jose</option>
            <option>Jean</option>
            <option>Jase</option>
          </select>
        </div>
      </div>

      {/* Grille du calendrier */}
      <div className="calendrier-grid">
        {/* En-tête des jours */}
        <div className="days-header">
          <div className="day-header"></div>
          {joursSemaine.map(day => (
            <div key={day} className="day-header">{day}</div>
          ))}
        </div>

        {/* Corps du calendrier avec créneaux horaires */}
        <div className="time-slots">
          {timeSlots.map((time, timeIndex) => (
            <div key={time} className="time-row">
              <div className="time-label">{time}</div>
              {joursSemaine.map(day => (
                <div key={`${day}-${time}`} className="day-cell">
                  {planningData[day] && timeIndex === 1 && (
                    <>
                      {planningData[day].map((person, index) => (
                        <div 
                          key={`${day}-${person}-${index}`} 
                          className="person-item"
                          style={{ 
                            backgroundColor: personnes.find(p => p.name === person)?.color || '#e3f2fd'
                          }}
                        >
                          {person}
                        </div>
                      ))}
                    </>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Modale Ajouter Trajet */}
      <AjouterTrajet 
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSave={handleSaveTrajet}
      />
    </div>
  );
};

export default Calendrier;
